export const BODY: string = "\n<p>تصویر کے کچھ حصے شیئر نہیں کرنے چاہیے۔ پس منظر میں چہرہ، خط پر پتہ، یا اسکرین پر پاس ورڈ، اگر وہ غلط ہاتھوں میں پہنچ جائیں تو حقیقی نقصان پہنچا سکتے ہیں۔</p>\n<p>بلر اور پکسلیٹ ان تفصیل کو چھپانے کے دو طریقے ہیں۔ دونوں علاقے کو ناقابلِ پڑھائی بنا دیتے ہیں، مگر وہ مختلف لگتے ہیں اور مختلف طریقے سے حفاظت کرتے ہیں۔</p>\n<p>اس گائیڈ میں دونوں طریقے بتائے گئے ہیں، ہر ایک کب استعمال کریں، اور انہیں صاف طریقے سے کیسے لگائیں۔ اس میں برش اور پوری تصویر موڈ، شدت سیٹنگ، اور وہ غلطیاں شامل ہیں جن سے بچنا چاہیے۔</p>\n<h2 id=\"what-blur-does\">بلر تصویر کے ساتھ کیا کرتا ہے</h2>\n<p>بلر پڑوسی پکسلز کے رنگوں کا اوسط لے کر علاقے کو نرم کر دیتا ہے۔ تیز کنارے پگھل جاتے ہیں، متن ناقابلِ پڑھائی ہو جاتا ہے، اور چہروں کی خصوصیات ختم ہو جاتی ہیں۔</p>\n<p>ہلکا بلر تفصیل کو صرف کچھ نرم کرتا ہے، جبکہ مضبوط بلر علاقے کو رنگ کی ہموار دھلائی میں بدل دیتا ہے۔ شدت سیٹنگ طے کرتی ہے کہ کتنی معلومات ختم ہوتی ہے۔</p>\n<p>بلر پس منظر اور نرم گمنامی کے لیے بہترین ہے۔ ہلکا دھندلا پس منظر تصویر کو قدرتی رکھتا ہے جبکہ توجہ موضوع کی طرف دھکیلتا ہے۔</p>\n<p>حساس معلومات چھپانے کے لیے بلر مضبوط ہونا چاہیے۔ چہرے یا پتے پر ہلکا بلر کبھی کبھی تیز کیا جا سکتا ہے، اس لیے پرائیویسی کے لیے بھاری بلر استعمال کریں۔</p>\n<h2 id=\"what-pixelate-does\">پکسلیٹ تصویر کے ساتھ کیا کرتا ہے</h2>\n<p>پکسلیٹ علاقے کو ٹھوس رنگ کے بڑے بلاکس سے بدل دیتا ہے، جیسے موزیک۔ ہر بلاک اس کے نیچے والے پکسلز کا اوسط رنگ ہوتا ہے، اس لیے تمام باریک تفصیل ختم ہو جاتی ہے۔</p>\n<p>بلاک سائز شدت کو کنٹرول کرتا ہے۔ چھوٹے بلاکس شکل کا کھردرا اشارہ رکھتے ہیں، جبکہ بڑے بلاکس علاقے کو رنگ کے چند فلیٹ مربعوں تک کم کر دیتے ہیں۔</p>\n<p>پکسلیشن جان بوجھ کر سینسر شدہ لگتی ہے، جو تب مفید ہوتا ہے جب آپ چاہیں کہ دیکھنے والا جانے کہ کچھ چھپایا گیا تھا۔ دھندلا چہرہ فنکارانہ لگتا ہے، جبکہ پکسلیٹ شدہ چہرہ واضح سینسر لگتا ہے۔</p>\n<p>متن چھپانے کے لیے پکسلیشن اکثر ہلکے بلر سے محفوظ ہوتی ہے۔ بڑے بلاکس والا موزیک حروف کی شکلیں مکمل تباہ کر دیتا ہے، جبکہ نرم بلر انہیں جزوی طور پر چھوڑ سکتا ہے۔</p>\n<h2 id=\"why-censor-images\">لوگ تصاویر کو بلر اور پکسلیٹ کیوں کرتے ہیں</h2>\n<p>پرائیویسی اہم ترین وجہ ہے۔ آن لائن شیئر شدہ تصویر چہرے، پتے، نمبر پلیٹ اور دستاویزات ظاہر کر سکتی ہے، اور ان تفصیل کو سینسر کرنا تصویر میں موجود لوگوں کی حفاظت کرتا ہے۔</p>\n<p>والدین خاندانی تصاویر کو عوامی طور پر پوسٹ کرنے سے پہلے اپنے بچوں کے چہرے دھندلا کرتے ہیں۔ بچوں نے آن لائن ہونے کی رضامندی نہیں دی، اور بلر انہیں تلاش کے قابل نتائج سے باہر رکھتا ہے۔</p>\n<p>صحافی اور محقق حساس کہانیوں میں چہرے پکسلیٹ کرتے ہیں۔ جس ماخذ نے گمنامی کی شرط پر بات کی اس کی شناخت چھپانی چاہیے، صرف نرم کرنا نہیں۔</p>\n<p>کاروبار اسکرین شاٹس میں اسکرینیں دھندلا کرتے ہیں۔ ڈیش بورڈ کا اسکرین شاٹ گاہکوں کے نام، اندرونی URL، یا پاس ورڈ ظاہر کر سکتا ہے، اور احتیاط والا بلر انہیں شیئر کرنے سے پہلے ہٹا دیتا ہے۔</p>\n<h2 id=\"brush-area-mode\">برش ایریا موڈ: تفصیل پر پینٹ کرنا</h2>\n<p>برش ایریا موڈ آپ کو بلر یا پکسلیشن کو بالکل وہاں پینٹ کرنے دیتا ہے جہاں ضرورت ہو۔ آپ برش کو چہرے، نمبر پلیٹ، یا متن کی لائن پر کھینچتے ہیں، اور صرف وہ جگہیں متاثر ہوتی ہیں۔</p>\n<p>باقی تصویر تیز رہتی ہے۔ یہ درستگی ہی برش موڈ کو زیادہ تر پرائیویسی کام کے لیے درست انتخاب بناتی ہے، جہاں تصویر کا صرف چھوٹا حصہ چھپانا ہوتا ہے۔</p>\n<p>برش سائز اہمیت رکھتا ہے۔ بڑا برش چند اسٹروک میں چہرہ ڈھانپ لیتا ہے، جبکہ چھوٹا برش آپ کو ایک لفظ یا چھوٹی تفصیل کے ارد گرد بغیر آس پاس کو چھوئے ٹریس کرنے دیتا ہے۔</p>\n<p>اگر پینٹ کرتے وقت غلطی ہو تو انڈو بٹن آخری اسٹروک ہٹا دیتا ہے۔ آپ برش کو مکمل ری سیٹ بھی کر سکتے ہیں اور دوبارہ شروع کر سکتے ہیں، جو غلطی کو ٹھیک کرنے کی کوشش سے تیز ہوتا ہے۔</p>\n<h2 id=\"whole-image-mode\">پوری تصویر موڈ: سب کچھ دھندلا کرنا</h2>\n<p>پوری تصویر موڈ اثر کو ایک ساتھ پوری تصویر پر لگاتا ہے۔ یہ درست انتخاب ہے جب پوری تصویر حساس ہو، یا جب آپ متن یا پریزنٹیشن سلائیڈ کے لیے دھندلا پس منظر چاہتے ہوں۔</p>\n<p>مکمل دھندلی تصویر متن کے لیے اچھا پس منظر بناتی ہے۔ رنگ اور مزاج باقی رہتے ہیں، مگر اوپر والے الفاظ سے کچھ بھی توجہ نہیں ہٹاتا۔</p>\n<p>پوری تصویر موڈ پر جانے سے ہدف علاقہ آپ کے برش اسٹروک سے پورے فریم میں بدل جاتا ہے۔ ٹول موجودہ بلر یا پکسلیشن شدت کو ہر چیز پر لگاتا ہے۔</p>\n<p>پرائیویسی کے لیے پوری تصویر موڈ احتیاط سے استعمال کریں۔ مکمل دھندلی تصویر سب کچھ چھپاتی ہے، مگر وہ موضوع کو بھی چھپاتی ہے، اس لیے شیئر کرنے کے لیے یہ شاذ و نادر ہی درست انتخاب ہوتا ہے۔</p>\n<h2 id=\"smooth-blur-strength\">ہموار بلر شدت: کتنا مضبوط کافی ہے؟</h2>\n<p>بلر شدت ایک پیمانہ ہے، اور درست قدر اس پر منحصر ہے کہ آپ کیا چھپا رہے ہیں۔ پس منظر کو صرف ہلکا بلر چاہیے ہوتا ہے، جبکہ چہرے یا پتے کو بھاری بلر چاہیے ہوتا ہے۔</p>\n<p>چہروں کے لیے مضبوط بلر استعمال کریں جو تمام پہچاننے کے قابل خصوصیات ہٹا دے۔ ہلکا بلر جو آنکھیں اور مسکراہٹ نظر آنے دے وہ کسی کی حفاظت نہیں کرتا۔</p>\n<p>متن کے لیے بھی مضبوط بلر چاہیے ہوتا ہے۔ ہلکا دھندلا لفظ کبھی کبھی اس کی لمبائی اور شکل سے اندازہ لگایا جا سکتا ہے، خاص طور پر جب سیاق اسے ظاہر کر دے۔</p>\n<p>نتیجہ کو زوم کر کے آزمائیں۔ اگر آپ پورے سائز پر متن پڑھ سکتے ہیں یا چہرہ پہچان سکتے ہیں تو شدت بڑھائیں اور دوبارہ چیک کریں۔</p>\n<h2 id=\"mosaic-block-size\">موزیک بلاک سائز: بڑے بلاکس، محفوظ سینسرنگ</h2>\n<p>موزیک بلاک سائز بلر شدت کی طرح کام کرتا ہے: بڑے بلاکس زیادہ چھپاتے ہیں۔ چھوٹا بلاک سائز علاقے کی کھردری شکل رکھتا ہے، جبکہ بڑا بلاک سائز اسے چند فلیٹ مربعوں تک کم کر دیتا ہے۔</p>\n<p>چھوٹے اسکرین شاٹس کے لیے درمیانہ بلاک سائز استعمال کریں۔ متن چھوٹا ہوتا ہے، اس لیے معمولی بلاک بھی حروف کی شکلیں مکمل تباہ کر دیتا ہے۔</p>\n<p>بڑی تصاویر کے لیے بڑے بلاکس استعمال کریں۔ اعلیٰ ریزولوشن تصویر میں چہرے کو خصوصیات چھپانے کے لیے بڑے بلاکس چاہیے ہوتے ہیں، کیونکہ چھوٹے بلاکس آنکھیں اور منہ چھوڑ دیتے ہیں۔</p>\n<p>شک ہو تو بڑا جائیں۔ کچھ زیادہ مضبوط موزیک جان بوجھ کر لگتا ہے، جبکہ کچھ کمزور موزیک حساس تفصیل کو پڑھنے کے قابل چھوڑ دیتا ہے۔</p>\n<h2 id=\"brush-size-settings\">برش سائز: اوزار کو تفصیل سے ملانا</h2>\n<p>برش سائز اس تفصیل سے ملنا چاہیے جسے آپ چھپا رہے ہیں۔ چہرے کو بڑا برش، نمبر پلیٹ کو درمیانہ، اور ایک لفظ کو چھوٹا برش چاہیے ہوتا ہے۔</p>\n<p>بہت بڑا برش آپ کے ارادے سے زیادہ سینسر کرتا ہے۔ یہ پڑوسی چہرہ یا تصویر کا مفید حصہ ڈھانپ سکتا ہے جسے چھپانے کی ضرورت نہیں تھی۔</p>\n<p>بہت چھوٹا برش بڑے علاقے کو ڈھانپنے میں بہت سے اسٹروک لیتا ہے، اور اسٹروک کے درمیان خلا حساس تفصیل کی پٹیاں نظر آنے دے سکتا ہے۔</p>\n<p>کام کرتے وقت برش سائز ایڈجسٹ کریں۔ مرکزی علاقے کے لیے بڑے سے شروع کریں، پھر کنارے صاف کرنے اور چھوٹی ہوئی جگہیں ڈھانپنے کے لیے چھوٹے برش پر جائیں۔</p>\n<h2 id=\"hiding-faces\">چہرے درست طریقے سے چھپانا</h2>\n<p>چہرے کو چھپانے کے لیے مکمل کوریج چاہیے ہوتی ہے۔ آنکھیں، ناک، منہ اور بالوں کی لکیر سب شناختی معلومات رکھتے ہیں، اس لیے سینسر شدہ علاقے کو پورا سر ڈھانپنا چاہیے۔</p>\n<p>چہروں کے لیے پکسلیشن اکثر محفوظ انتخاب ہوتی ہے۔ بڑے بلاکس والا موزیک خصوصیات کو مکمل تباہ کر دیتا ہے، جبکہ ہلکا بلر پہچاننے کے لیے کافی چھوڑ سکتا ہے۔</p>\n<p>صرف آنکھیں نہیں، پورا سر ڈھانپیں۔ آنکھوں پر کالی پٹی فلمی کلیشے ہے، حقیقی حفاظت نہیں، کیونکہ باقی چہرہ پھر بھی پہچاننے کے قابل رہتا ہے۔</p>\n<p>نتیجہ پورے سائز پر چیک کریں۔ سینسر شدہ چہرے پر زوم کریں اور تصدیق کریں کہ کوئی خصوصیت نظر نہیں آتی، پھر پس منظر میں عکس چیک کریں جو چہرہ دکھا سکتے ہیں۔</p>\n<h2 id=\"hiding-text-and-numbers\">متن، نمبر اور پتے چھپانا</h2>\n<p>متن چہروں سے چھپانا مشکل ہوتا ہے، کیونکہ جزوی حرف بھی لفظ ظاہر کر سکتا ہے۔ لائسنس پلیٹ، پتہ، یا پاس ورڈ کو مکمل کوریج چاہیے ہوتی ہے۔</p>\n<p>بڑے بلاکس والی پکسلیشن متن کے لیے محفوظ ترین طریقہ ہے۔ یہ حروف کی شکلیں مکمل تباہ کر دیتی ہے، جبکہ نرم بلر الفاظ کا خاکہ پڑھنے کے قابل چھوڑ سکتا ہے۔</p>\n<p>صرف حساس لفظ نہیں، پوری لائن ڈھانپیں۔ لائن کی لمبائی اور ارد گرد کے الفاظ چھپے ہوئے حصے کو ظاہر کر سکتے ہیں، اس لیے فراخی سے سینسر کریں۔</p>\n<p>تصویر میں کہیں اور وہی متن چیک کریں۔ لفافے پر پتہ پس منظر میں خط پر بھی ظاہر ہو سکتا ہے، اور دونوں کاپیوں کو سینسر کرنا چاہیے۔</p>\n<h2 id=\"hiding-backgrounds\">توجہ اور پرائیویسی کے لیے پس منظر دھندلا کرنا</h2>\n<p>دھندلا پس منظر موضوع کو نمایاں کرتا ہے۔ پورٹریٹ فوٹوگرافرز دہائیوں سے یہ اثر استعمال کرتے رہے ہیں، اور ڈیجیٹل بلر تصویر لینے کے بعد وہی نتیجہ دیتا ہے۔</p>\n<p>برش سے پس منظر پر بلر پینٹ کریں، موضوع کو تیز رکھیں۔ تیز موضوع اور نرم پس منظر کے درمیان فرق آنکھ کو بالکل وہیں کھینچتا ہے جہاں آپ چاہتے ہیں۔</p>\n<p>پرائیویسی کے لیے دھندلا پس منظر مقام چھپا سکتا ہے۔ پس منظر میں گلی کا نشان، مکان نمبر، یا پہچاننے کے قابل عمارت بتا سکتی ہے کہ تصویر کہاں لی گئی تھی۔</p>\n<p>پس منظر کے لیے ہلکا بلر اور حساس تفصیل کے لیے بھاری بلر استعمال کریں۔ دونوں شدتیں مختلف مقاصد پورا کرتی ہیں، اور انہیں ملانا دونوں کو کمزور کرتا ہے۔</p>\n<h2 id=\"formats-and-transparency\">فارمیٹ اور شفافیت</h2>\n<p>ٹول عام تصویری فارمیٹ قبول کرتا ہے، جن میں JPG، PNG، WebP اور HEIC شامل ہیں، اور فائلیں 20 MB تک ہو سکتی ہیں۔ آپ اپنی ضرورت کے مطابق JPG، PNG یا WebP میں ایکسپورٹ کر سکتے ہیں۔</p>\n<p>PNG یا WebP میں ایکسپورٹ کرنے سے بنیادی تصویر میں شفافیت محفوظ رہتی ہے۔ اگر آپ کا ماخذ شفاف PNG گرافک ہے تو سینسر شدہ ایکسپورٹ شفاف جگہوں کو برقرار رکھتی ہے۔</p>\n<p>تصاویر کے لیے JPG اکثر بہترین ایکسپورٹ ہوتا ہے۔ یہ فائل سائز چھوٹا رکھتا ہے اور ہر جگہ کام کرتا ہے، اور سینسر شدہ علاقے صاف کمپریس ہوتے ہیں۔</p>\n<p>کوالٹی سلائیڈر JPG اور WebP ایکسپورٹ کے لیے ظاہر ہوتا ہے اور PNG کے لیے چھپ جاتا ہے، کیونکہ PNG لاس لیس ہے اور اس کی کوئی کوالٹی سیٹنگ نہیں ہوتی۔</p>\n<h2 id=\"privacy-local-processing\">پرائیویسی: اپ لوڈ کیے بغیر سینسر کرنا</h2>\n<p>تمام بلر اور پکسلیٹ آپ کے براؤزر میں ہوتی ہے۔ آپ کی تصاویر کبھی سرور پر اپ لوڈ نہیں ہوتیں، جو اہمیت رکھتا ہے جب تصاویر میں چہرے، شناختی کارڈ، یا نجی پتے ہوں۔</p>\n<p>یہ سینسرنگ ٹول کی سب سے اہم خصوصیت ہے۔ جس تصویر کو چھپانا ہو اسے چہرہ دھندلا کرنے کے لیے ایسے سرور پر کبھی نہیں بھیجنا چاہیے جسے آپ دیکھ نہیں سکتے۔</p>\n<p>ٹول ایکسپورٹ پر EXIF GPS ڈیٹا بھی ہٹا دیتا ہے۔ ٹول سے ڈاؤن لوڈ شدہ سینسر شدہ تصویر میں یہ ریکارڈ نہیں ہوتا کہ وہ کہاں لی گئی تھی، جو حفاظت کی دوسری تہہ ہے۔</p>\n<p>غیر سینسر شدہ اصل کو محفوظ اور الگ رکھیں۔ ایک بار جب آپ سینسر شدہ ورژن شیئر کر دیں تو اصل ہی واحد کاپی ہوتی ہے جو پوری تصویر دکھاتی ہے۔</p>\n<h2 id=\"common-mistakes\">تصاویر سینسر کرتے وقت عام غلطیاں</h2>\n<p>سب سے عام غلطی بہت ہلکا سینسر کرنا ہے۔ چہرے پر نرم بلر یا متن پر چھوٹا موزیک تفصیل کو پڑھنے کے قابل چھوڑ سکتا ہے، جو پورے مقصد کو شکست دیتا ہے۔</p>\n<p>دوسری غلطی عکس چھوڑنا ہے۔ چہرہ اسی تصویر میں آئینے، کھڑکی، یا دھوپ کے چشمے میں ظاہر ہو سکتا ہے، اور ہر کاپی کو سینسر کرنا چاہیے۔</p>\n<p>لوگ میٹا ڈیٹا بھی بھول جاتے ہیں۔ دھندلے چہرے والی تصویر پھر بھی GPS کوآرڈینیٹ لے جا سکتی ہے جو بتاتے ہیں کہ وہ کہاں لی گئی تھی، اس لیے ایکسپورٹ سیٹنگ چیک کریں۔</p>\n<p>آخر میں، غلطی سے اصل شیئر نہ کریں۔ سینسر شدہ تصویر اور اس کا اصل اکثر ڈاؤن لوڈ فولڈر میں ساتھ ساتھ بیٹھے ہوتے ہیں، اور غلط والی منسلک کرنا سب کچھ ختم کر دیتا ہے۔</p>\n<h2 id=\"censoring-workflow\">محفوظ شیئرنگ کے لیے ورک فلو</h2>\n<p>اصل تصویر کھولیں اور ہر چیز کی فہرست بنائیں جسے چھپانا ہو: چہرے، پتے، نمبر پلیٹ، اسکرینیں، اور دستاویزات۔ سامنے کے ساتھ ساتھ پس منظر بھی چیک کریں۔</p>\n<p>ہر چیز پر برش سے پینٹ کریں، متن کے لیے پکسلیشن اور چہروں کے لیے مضبوط بلر یا موزیک استعمال کریں۔ ہر اسٹروک کے بعد زوم کر کے مکمل کوریج کی تصدیق کریں۔</p>\n<p>سینسر شدہ ورژن ایکسپورٹ کریں اور اسے پورے سائز پر چیک کریں۔ چھوٹے ہوئے عکس، پڑھنے کے قابل متن، اور پہلی بار چھوٹی ہوئی کوئی تفصیل تلاش کریں۔</p>\n<p>صرف سینسر شدہ فائل شیئر کریں۔ اصل کو الگ فولڈر میں رکھیں، اور اسے سینسر شدہ ورژن والے پیغام یا پوسٹ سے کبھی منسلک نہ کریں۔</p>\n<h2 id=\"blurring-for-video-thumbnails\">ویڈیو تھمب نیل اور کور کے لیے بلر</h2>\n<p>دھندلی تصویر ویڈیو تھمب نیل کے لیے اچھا پس منظر بناتی ہے۔ نرم رنگ مزاج طے کرتے ہیں، جبکہ اوپر عنوان متن تیز اور پڑھنے میں آسان رہتا ہے۔</p>\n<p>تھمب نیل کے لیے درمیانہ بلر کے ساتھ پوری تصویر موڈ استعمال کریں۔ تصویر منظر کے طور پر پہچاننے کے قابل ہونی چاہیے، مگر اتنی نرم کہ متن فریم پر حاوی ہو۔</p>\n<p>موضوع کو بلر میں کچھ نظر آنے دیں۔ صرف رنگ والا تھمب نیل خالی لگتا ہے، جبکہ متن کے پیچھے مدھم موضوع والا تھمب نیل جان بوجھ کر لگتا ہے۔</p>\n<p>تھمب نیل کو اعلیٰ کوالٹی سیٹنگ پر JPG میں ایکسپورٹ کریں۔ فائل کو چھوٹے سائز پر صاف لگنا چاہیے، اور کم کوالٹی ایکسپورٹ عنوان متن کو بھی نرم کر دے گی۔</p>\n<p>مرحلہ بہ مرحلہ عمل کے لیے <a href=\"/ur/blog/tasveer-kaise-blur-pixelate-karein/\">How to Blur or Pixelate an Image</a> دیکھیں۔ موازنے کے لیے <a href=\"/ur/blog/blur-vs-pixelate-tasveer/\">Blur vs Pixelate: Hiding Faces, Text and Details</a> پڑھیں، اور لوکیشن ہٹانے کے لیے <a href=\"/ur/tasveer-metadata-hatayein/\">Remove Image Metadata tool</a> استعمال کریں۔</p>\n";

